// ⚠️ ATENÇÃO: COLOQUE A STRING BASE64 DO SEU PDF AQUI ABAIXO: 
// É CRÍTICO que esta variável seja preenchida para o PDF funcionar.
const PDF_BASE_BASE64 = '';
// VARIÁVEIS GLOBAIS
let baseBytes = null; // Variável para armazenar os bytes do PDF Base
let fotoFile = null; // Variável global para armazenar o objeto File da foto
let contadorExames = 1; // Contador global para garantir IDs únicos

// --- FUNÇÕES AUXILIARES DE ARQUIVO E FORMULÁRIO ---

// Função utilitária para converter Base64 em ArrayBuffer (necessário para o PDFLib)
function base64ToBytes(base64) {
    // Remove o prefixo da Data URL (ex: 'data:application/pdf;base64,') se existir
    const base64Cleaned = base64.split(',')[1] || base64;

    // Decodifica a string Base64 binária
    const binaryString = atob(base64Cleaned);

    // Cria um array de bytes (Uint8Array)
    const len = binaryString.length;
    const bytes = new Uint8Array(len);
    for (let i = 0; i < len; i++) {
        bytes[i] = binaryString.charCodeAt(i);
    }
    // Retorna o ArrayBuffer para o PDFDocument.load()
    return bytes.buffer;
}

// Função para coletar o valor de um elemento HTML por ID
function getElementValue(id) {
    const el = document.getElementById(id);
    return el ? el.value : '';
}

// --- LÓGICA DE ITENS ADICIONAIS ---

function adicionarExameAdicional() {
    // Usa a variável global contadorExames
    contadorExames++;

    const templateElement = document.getElementById('graduacao-template');

    // Pega o HTML da template
    let htmlString = templateElement.innerHTML;

    // Substitui placeholders para garantir IDs únicos
    const novoExameId = 'graduacao-adicional-' + contadorExames;
    htmlString = htmlString.replace(/NUM_PLACEHOLDER/g, contadorExames)
        .replace(/id="(.+?)_X"/g, `id="$1_${contadorExames}"`) // Substitui IDs
        .replace(/for="(.+?)_X"/g, `for="$1_${contadorExames}"`); // Substitui 'for' nos labels

    // Envolve o HTML com a div principal
    const finalHtml = `<div class="row g-3 exame-adicional-item pt-4 mt-4" id="${novoExameId}">${htmlString}</div>`;

    // Adiciona o novo bloco ao DOM
    document.getElementById('graduacoes-adicionais').insertAdjacentHTML('beforeend', finalHtml);

    // Atualiza o onclick para a função de remover, usando o novo ID
    const removeButton = document.getElementById(novoExameId).querySelector('.btn-danger');
    if (removeButton) {
        removeButton.setAttribute('onclick', `removerExameAdicional('${novoExameId}')`);
    }
}

// --- FUNÇÃO GLOBAL, ACESSÍVEL PELO ONCLICK ---
function removerExameAdicional(idElemento) {
    const elemento = document.getElementById(idElemento);
    if (elemento) {
        elemento.remove();
    }
}
// --- FIM DA FUNÇÃO GLOBAL ---

document.addEventListener('DOMContentLoaded', () => {

    // Carrega o PDF Base (Usando a constante PDF_BASE_BASE64)
    try {
        if (typeof PDF_BASE_BASE64 !== 'undefined' && PDF_BASE_BASE64 && PDF_BASE_BASE64.length > 50) {
            baseBytes = base64ToBytes(PDF_BASE_BASE64);
            console.log("PDF base carregado (bytes) com sucesso via Base64.");
        } else {
            console.warn("PDF_BASE_BASE64 está vazio. Certifique-se de preenchê-lo com o conteúdo do seu PDF.");
        }
    } catch (error) {
        console.error("Erro ao carregar PDF base via Base64.", error);
    }


    // Inicializa Tooltips do Bootstrap 
    const tooltipTriggerList = document.querySelectorAll('[data-bs-toggle="tooltip"]')
    const tooltipList = [...tooltipTriggerList].map(tooltipTriggerEl => new bootstrap.Tooltip(tooltipTriggerEl))

    /* ---------- MÁSCARAS E PRÉ-VISUALIZAÇÃO ---------- */
    IMask(document.getElementById('cpf'), { mask: '000.000.000-00' });
    IMask(document.getElementById('rg'), { mask: '00.000.000-0' });
    IMask(document.getElementById('celular'), { mask: '(00) 00000-0000' });
    IMask(document.getElementById('cep'), { mask: '00000-000' });
    IMask(document.getElementById('altura'), { mask: '0.00' });
    IMask(document.getElementById('peso'), { mask: '000' });

    const fotoInput = document.getElementById('foto');
    const fotoPrev = document.getElementById('fotoPrev');

    // Lógica para pré-visualização da foto
    fotoInput.addEventListener('change', function (e) {
        const file = e.target.files[0];
        fotoFile = file; // Salva o objeto File na variável global
        if (file) {
            const reader = new FileReader();
            reader.onload = function (e) {
                fotoPrev.src = e.target.result;
                fotoPrev.classList.add('has-image');
            };
            reader.readAsDataURL(file);
        } else {
            // SVG placeholder
            fotoPrev.src = "data:image/svg+xml;charset=utf8,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 100 100'%3E%3Cpath fill='%23ccc' d='M50 0a50 50 0 1 0 0 100 50 50 0 0 0 0-100zm0 15a35 35 0 1 1 0 70 35 35 0 0 1 0-70zm-5 15a5 5 0 1 1-10 0 5 5 0 0 1 10 0zM50 40c-13.8 0-25 11.2-25 25v5h50v-5c0-13.8-11.2-25-25-25z'/%3E%3C/svg%3E";
            fotoPrev.classList.remove('has-image');
        }
    });


    /* ---------- GERAÇÃO DO PDF (LÓGICA DE SUBMISSÃO) ---------- */
    document.getElementById('formRequerimento').addEventListener('submit', async (event) => {

        event.preventDefault(); // Impede o envio padrão do formulário
        const form = event.target;

        // 1. Aplica a validação do Bootstrap
        form.classList.add('was-validated');

        // 2. Validação dos campos de formulário obrigatórios
        const invalidElements = form.querySelectorAll(':invalid');
        if (invalidElements.length > 0) {
            invalidElements[0].focus();
            alert("Por favor, preencha todos os campos obrigatórios do formulário.");
            return;
        }

        // 3. Validação do PDF Base
        if (!baseBytes) {
            alert("Erro: Arquivo PDF base não foi carregado corretamente.");
            return;
        }

        // 4. Validação dos campos de arquivo (inputs type="file")
        if (!fotoFile) {
            alert("Por favor, anexe a Foto 3x4 obrigatória.");
            return;
        }

        // O código só será executado se todas as validações passarem.
        const { PDFDocument, StandardFonts, rgb } = PDFLib;

        try {
            // Carrega o PDF base
            let pdfDoc = await PDFDocument.load(baseBytes);
            const helv = await pdfDoc.embedFont(StandardFonts.Helvetica);
            const page = pdfDoc.getPages()[0];
            const { width, height } = page.getSize();

            // Função para escrever texto em coordenadas do Scribus (pt)
            function writePt(id, x_pt, y_scribus_pt, size = 9, align = 'left') {
                const el = document.getElementById(id);
                let text = el ? el.value.toString() : "";

                // --- NOVA REGRA DO RG: Se o RG estiver vazio, tenta usar o CPF ---
                if (id === 'rg' && text.trim() === "") {
                    const cpfEl = document.getElementById('cpf');
                    if (cpfEl && cpfEl.value) {
                        text = cpfEl.value.toString();
                    }
                }

                if (!text) return; // Se ainda assim estiver vazio, sai da função sem escrever

                if (el && el.type === 'date') text = formatDateIfISO(el.value);

                // O valor 0.3 ajusta a linha base do texto
                const y = height - y_scribus_pt - size * 0.3;

                const tw = helv.widthOfTextAtSize(text, size);
                let x = x_pt;
                if (align === 'center') x = x_pt - tw / 2;
                else if (align === 'right') x = x_pt - tw;

                page.drawText(text, { x, y, size, font: helv, color: rgb(0, 0, 0) });
            }

            // Função para formatar a data (ISO para DD/MM/AAAA)
            function formatDateIfISO(val) {
                if (!val) return "";
                const m = String(val).match(/^(\d{4})-(\d{2})-(\d{2})$/);
                if (m) return m[3] + '/' + m[2] + '/' + m[1];
                return val;
            }


            // Mapeamento e preenchimento de campos fixos
            const campos = [

                { id: "nomeCompleto", x: 58.46, y: 159.03 },
                { id: "filiacao", x: 57.86, y: 190.06 },
                { id: "dataNascimento", x: 58.70, y: 224.00, isDate: true },
                { id: "natural", x: 144.60, y: 224.00 },
                { id: "nacionalidade", x: 348.54, y: 224.00 },
                { id: "estadoCivil", x: 57.42, y: 254.00 },
                { id: "instrucao", x: 144.00, y: 254.00 },
                { id: "profissao", x: 345.74, y: 254.00 },
                { id: "residencia", x: 58.86, y: 284.60 },
                { id: "bairro", x: 58.66, y: 317.09 },
                { id: "cidade", x: 294.69, y: 317.09 },
                { id: "uf", x: 525.22, y: 319.09 },
                { id: "cep", x: 58.06, y: 350.86 },
                { id: "celular", x: 157.49, y: 348.66 },
                { id: "email", x: 139.03, y: 493.82 },
                { id: "peso", x: 57.86, y: 383.49 },
                { id: "altura", x: 156.49, y: 383.49 },
                { id: "cor", x: 256.32, y: 383.49 },
                { id: "sangue", x: 355.96, y: 383.89 },
                { id: "sexo", x: 467.32, y: 383.89 },
                { id: "rg", x: 57.86, y: 416.00 },
                { id: "orgaoEmissor", x: 186.77, y: 414.85 },
                { id: "emissaoRG", x: 279.00, y: 416.00, isDate: true },
                { id: "cpf", x: 361.77, y: 416.00 },
                { id: "inicioTKD", x: 57.86, y: 448.11, isDate: true },
                { id: "entidade", x: 142.97, y: 448.31 },
                { id: "professor", x: 59.46, y: 479.09 },
                { id: "danProfessor", x: 286.91, y: 479.09 },
                { id: "mestre", x: 325.02, y: 479.09 },
                { id: "danMestre", x: 522.69, y: 479.09 },
                { id: "dataReq", x: 347.25, y: 756.40, isDate: true }

            ];
            campos.forEach(campo => writePt(campo.id, campo.x, campo.y));


            // --- DADOS DE GRADUAÇÃO (PRIMEIRO ITEM) ---
            const tipo = getElementValue("tipoGraduacao");
            const num = getElementValue("numGraduacao");
            const gradData = getElementValue("gradData");
            const gradLocal = getElementValue("gradLocal");
            const gradGMestre = getElementValue("gradGMestre");


            const linhaGraduacao = {
                DAN: {
                    1: { xCheck: 65.02, y: 551.60, xData: 126.52, xLocal: 184.92, xMestre: 284.97 },
                    2: { xCheck: 65.02, y: 565.30, xData: 126.52, xLocal: 184.92, xMestre: 284.97 },
                    3: { xCheck: 65.02, y: 578.41, xData: 126.52, xLocal: 184.92, xMestre: 284.97 },
                    4: { xCheck: 65.02, y: 593.30, xData: 126.52, xLocal: 184.92, xMestre: 284.97 },
                    5: { xCheck: 65.02, y: 607.23, xData: 126.52, xLocal: 184.92, xMestre: 284.97 },
                    6: { xCheck: 65.02, y: 621.63, xData: 126.52, xLocal: 184.92, xMestre: 284.97 },
                    7: { xCheck: 65.02, y: 635.03, xData: 126.52, xLocal: 184.92, xMestre: 284.97 },
                    8: { xCheck: 65.02, y: 649.03, xData: 126.52, xLocal: 184.92, xMestre: 284.97 },
                    9: { xCheck: 65.02, y: 662.83, xData: 126.52, xLocal: 184.92, xMestre: 284.97 }
                },
                GUB: {
                    1: { xCheck: 95.98, y: 662.83, xData: 126.52, xLocal: 184.92, xMestre: 284.97 },
                    2: { xCheck: 95.98, y: 649.03, xData: 126.52, xLocal: 184.92, xMestre: 284.97 },
                    3: { xCheck: 95.98, y: 635.03, xData: 126.52, xLocal: 184.92, xMestre: 284.97 },
                    4: { xCheck: 95.98, y: 621.63, xData: 126.52, xLocal: 184.92, xMestre: 284.97 },
                    5: { xCheck: 95.98, y: 607.23, xData: 126.52, xLocal: 184.92, xMestre: 284.97 },
                    6: { xCheck: 95.98, y: 593.30, xData: 126.52, xLocal: 184.92, xMestre: 284.97 },
                    7: { xCheck: 95.98, y: 578.41, xData: 126.52, xLocal: 184.92, xMestre: 284.97 },
                    8: { xCheck: 95.98, y: 565.30, xData: 126.52, xLocal: 184.92, xMestre: 284.97 },
                    9: { xCheck: 95.98, y: 551.60, xData: 126.52, xLocal: 184.92, xMestre: 284.97 }
                }
            };


            // Preenche a primeira graduação
            if (tipo && num && linhaGraduacao[tipo] && linhaGraduacao[tipo][num]) {
                const pos = linhaGraduacao[tipo][num];
                page.drawText("X", { x: pos.xCheck, y: height - pos.y, size: 12, font: helv, color: rgb(1, 0, 0) });
                if (gradData) page.drawText(formatDateIfISO(gradData), { x: pos.xData, y: height - pos.y, size: 9, font: helv });
                if (gradLocal) page.drawText(gradLocal, { x: pos.xLocal, y: height - pos.y, size: 9, font: helv });
                if (gradGMestre) page.drawText(gradGMestre, { x: pos.xMestre, y: height - pos.y, size: 9, font: helv });
            }

            // --- DADOS DE GRADUAÇÃO ADICIONAL (LOOP CORRIGIDO) ---
            const adicionaisContainers = document.getElementById('graduacoes-adicionais').children;

            for (let i = 0; i < adicionaisContainers.length; i++) {

                const counter = i + 2;
                const container = adicionaisContainers[i];

                if (container && container.classList.contains('exame-adicional-item')) {

                    // Coleta os dados dinâmicos do item atual usando getElementValue
                    const tipoAdd = getElementValue(`tipoGraduacao_${counter}`);
                    const numAdd = getElementValue(`numGraduacao_${counter}`);
                    const gradDataAdd = getElementValue(`gradData_${counter}`);
                    const gradLocalAdd = getElementValue(`gradLocal_${counter}`);
                    const gradGMestreAdd = getElementValue(`gradGMestre_${counter}`);

                    const tipo = tipoAdd;
                    const num = String(numAdd);

                    if (tipo && num && linhaGraduacao[tipo] && linhaGraduacao[tipo][num]) {
                        const pos = linhaGraduacao[tipo][num];

                        // Desenha o "X" na posição correta (Cor RGB corrigida para Black)
                        page.drawText("X", { x: pos.xCheck, y: height - pos.y, size: 12, font: helv, color: rgb(1, 0, 0) });

                        if (gradDataAdd) page.drawText(formatDateIfISO(gradDataAdd), { x: pos.xData, y: height - pos.y, size: 9, font: helv });
                        if (gradLocalAdd) page.drawText(gradLocalAdd, { x: pos.xLocal, y: height - pos.y, size: 9, font: helv });
                        if (gradGMestreAdd) page.drawText(gradGMestreAdd, { x: pos.xMestre, y: height - pos.y, size: 9, font: helv });
                    }
                }
            }

            // --- INSERÇÃO DA FOTO ---
            if (fotoFile) {
                const fotoBytes = await fotoFile.arrayBuffer();
                const fotoImg = fotoFile.type.includes("png")
                    ? await pdfDoc.embedPng(fotoBytes)
                    : await pdfDoc.embedJpg(fotoBytes);

                // Posição ajustada no PDF (Coordenadas de exemplo)
                page.drawImage(fotoImg, {
                    x: 456.44,
                    y: height - 684.00 - 120,
                    width: 113,
                    height: 123
                });
            }

            const pdfBytes = await pdfDoc.save();
            const blob = new Blob([pdfBytes], { type: "application/pdf" });
            const pdfUrl = URL.createObjectURL(blob); // <-- Salvamos a URL aqui

            const link = document.createElement('a');
            link.href = pdfUrl; // Usa a URL criada

            // Geração do nome do arquivo
            const nomeCompletoElement = document.getElementById('nomeCompleto');
            let nomeArquivo = "Sem-Nome";
            if (nomeCompletoElement && nomeCompletoElement.value) {
                // Usamos o método replaceAll (ou replace(/ /g, '-'))
                nomeArquivo = nomeCompletoElement.value.trim().replace(/ /g, '-').replace(/[^a-zA-Z0-9-]/g, '');
            }
            const downloadFileName = `Requerimento-FTKDERJ-${nomeArquivo}.pdf`; // Nome final do arquivo
            link.download = downloadFileName;

            // 1. TENTATIVA AUTOMÁTICA DE DOWNLOAD (Pode ser bloqueada)
            link.click();

            // 2. SALVAMENTO DA URL E NOME NO LOCALSTORAGE PARA O BOTÃO DE BACKUP
            localStorage.setItem('generatedPdfUrl', pdfUrl);
            localStorage.setItem('generatedPdfName', downloadFileName);

            const formLink = "https://docs.google.com/forms/d/e/1FAIpQLSeTcSGOQflKGkW8WbC9xvVkzTYSyBEbCS1U6hXHWZ5ms_7amw/viewform?usp=sharing&ouid=104699002103410869085";

            // HTML da tela de sucesso (com o botão "Baixar Novamente")
            const successHtml = `
                <div class="d-flex flex-column align-items-center justify-content-center" style="min-height: 100vh; text-align: center; padding: 20px;">
                    <h1 class="text-success mb-4">✅ Arquivo Gerado com Sucesso!</h1>
                    <p class="lead">O download do arquivo **${downloadFileName}** deve ter sido iniciado. Verifique sua pasta de downloads.</p>
                    
                    <button id="downloadBtn" class="btn btn-warning btn-lg mt-3 shadow">
                        ⚠️ Baixar Requerimento Novamente (Se não iniciou)
                    </button>
                    
                    <hr class="w-50 my-4">
                    <h2 class="mb-3 text-primary">👉 Próximo Passo Importante:</h2>
                    <p>Para finalizar sua solicitação, por favor, responda ao nosso formulário de confirmação:</p>
                    <a href="${formLink}" target="_blank" class="btn btn-primary btn-lg mt-3 shadow">
                        Responder Formulário de Confirmação
                    </a>
                    <p class="mt-3 text-muted">Agradecemos sua colaboração e atenção!</p>
                </div>
            `;

            // Função para ser executada após a mudança de tela
            function setupDownloadFallback() {
                const downloadBtn = document.getElementById('downloadBtn');
                if (downloadBtn) {
                    downloadBtn.addEventListener('click', () => {
                        // Pega a URL e o nome do arquivo salvos
                        const savedUrl = localStorage.getItem('generatedPdfUrl');
                        const savedName = localStorage.getItem('generatedPdfName');

                        if (savedUrl && savedName) {
                            const fallbackLink = document.createElement('a');
                            fallbackLink.href = savedUrl;
                            fallbackLink.download = savedName;

                            // O clique explícito no botão permite o download
                            fallbackLink.click();
                        } else {
                            // Caso a URL tenha sumido (raro)
                            alert("Erro: O arquivo PDF não foi encontrado no cache local. Por favor, refaça o processo.");
                        }
                    });
                }
            }


            // Substitui o conteúdo da página após um pequeno atraso.
            setTimeout(() => {
                document.body.innerHTML = successHtml;
                // Configura o evento de clique para o novo botão APÓS o HTML ser injetado
                setupDownloadFallback();
            }, 500);

        } catch (error) {
            console.error(error);
            alert("Ocorreu um erro ao gerar o PDF. Verifique o console para mais detalhes.");
        }
    });
});